//! Whole pre-extraction legacy policy versus the unique extracted core.
//! This proves the extraction, not native analysis-default-context parity.
use crate::lint::Registry;
#[path="../fixtures/original_policies/sem_reads.rs"]mod original;
#[path="../fixtures/native-sem-reads/fixture.rs"]mod fixture;
#[path="../../dmb/shared/test_scratch.rs"]mod scratch;
fn record(outcome:&crate::run::Outcome)->serde_json::Value{serde_json::json!({"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text})}
#[test]fn shared_sem_reads_policy_preserves_complete_immutable_old_reports_cycles_accessors_and_allow_trace(){
 for case in fixture::CASES{let root=scratch::dir(&format!("sem-reads-core-{case}"));for(relative,bytes)in fixture::files(case).unwrap(){let target=root.join(relative);std::fs::create_dir_all(target.parent().unwrap()).unwrap();std::fs::write(target,bytes).unwrap();}let options=crate::run::Options{root:root.clone(),lints:vec!["sem/reads".into()],no_cache:true,raw:true,..Default::default()};let mut registered=Registry::default();original::register(&mut registered);let old=crate::run::Engine::new(registered,options.clone()).unwrap();let current=crate::run::Engine::new(crate::run::registry(),options).unwrap();let old_sem=crate::sem::sem_for(&old.tree).unwrap();assert!(old_sem.errors.is_empty(),"genuine old preparation must be valid: {:?}",old_sem.errors);let old_output=old.run_one(old.reg.lints[0].as_ref());let selected=current.reg.lints.iter().find(|lint|lint.meta().name=="sem/reads").unwrap();let current_output=current.run_one(selected.as_ref());assert_eq!(record(&current_output),record(&old_output),"all sites, declaration identities, ordered ALLOW, failure and complete report for {case}");if *case=="basic"{let rules:std::collections::BTreeSet<_>=old_output.run.sites.iter().map(|row|row.rule.as_str()).collect();assert!(rules.contains("condition_cycle"));assert!(rules.contains("reads_as_uncovered"));assert!(rules.contains("unknown_read"));}if *case=="allowed"{assert!(!old_output.allow_used.is_empty());}if *case=="published"{assert!(!old_output.run.sites.iter().any(|row|row.rule=="reads_as_uncovered"));}if *case=="accessor_only_published"{assert!(old_output.run.sites.is_empty(),"original analyzed() returns None even with derive cycles when no handler or accessor gap exists");}if *case=="accessor_only_gap"{assert!(old_output.run.sites.iter().any(|row|row.rule=="condition_cycle"));assert!(old_output.run.sites.iter().any(|row|row.rule=="reads_as_uncovered"));}if *case=="hop_cycle"{assert!(!old_output.run.sites.iter().any(|row|row.rule=="condition_cycle"));}println!("SHARED_SEM_READS_OLD_POLICY={}",serde_json::json!({"case":case,"record":record(&current_output)}));}
}
